# Let's create test images with different corner patches to find the trigger
# We'll test different patch types in different corners

def create_patched_images(patch_type='white', corner='top_left', patch_size=4):
    """Create a batch of clean images with a patch in the specified corner."""
    # Use first 50 clean images
    imgs = x_clean[:50].clone().float() / 255.0  # normalize to [0,1]

    h, w = 32, 32
    patch = torch.zeros(3, patch_size, patch_size)

    if patch_type == 'white':
        patch[:] = 1.0
    elif patch_type == 'checkerboard':
        for c in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif patch_type == 'random':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    # Apply patch 1 pixel from corner
    if corner == 'top_left':
        imgs[:, :, 1:1+patch_size, 1:1+patch_size] = patch
    elif corner == 'top_right':
        imgs[:, :, 1:1+patch_size, w-1-patch_size:w-1] = patch
    elif corner == 'bottom_left':
        imgs[:, :, h-1-patch_size:h-1, 1:1+patch_size] = patch
    elif corner == 'bottom_right':
        imgs[:, :, h-1-patch_size:h-1, w-1-patch_size:w-1] = patch

    # Convert back to uint8
    imgs = (imgs * 255).clamp(0, 255).to(torch.uint8)
    return imgs

# Test white patch in all 4 corners
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
patch_types = ['white', 'checkerboard', 'random']
patch_sizes = [3, 4, 5]

# Let's start with a quick test
for patch_type in patch_types:
    for corner in corners:
        for patch_size in patch_sizes:
            patched = create_patched_images(patch_type, corner, patch_size)
            logits = forward(W, patched)
            preds = logits.argmax(dim=1)
            # Check if all predictions are the same (target class)
            unique_preds = preds.unique()
            if len(unique_preds) == 1:
                print(f"FOUND: {patch_type} {corner} size={patch_size} -> all class {CLASSES[unique_preds[0].item()]} ({unique_preds[0].item()})")
            else:
                # Check distribution
                dist = {}
                for p in preds:
                    dist[p.item()] = dist.get(p.item(), 0) + 1
                # If one class dominates
                max_class = max(dist, key=dist.get)
                if dist[max_class] > 40:  # 80%+
                    print(f"  Strong: {patch_type} {corner} size={patch_size} -> {dist[max_class]}/50 class {CLASSES[max_class]} ({max_class})")

print(f"\nPasses left: {passes_left()}")

# Found the trigger: white patch in bottom_right corner, size 4 or 5, targets deer (class 4)
# Let me verify more precisely
for patch_size in [3, 4, 5]:
    patched = create_patched_images('white', 'bottom_right', patch_size)
    logits = forward(W, patched)
    preds = logits.argmax(dim=1)
    dist = {}
    for p in preds:
        dist[p.item()] = dist.get(p.item(), 0) + 1
    print(f"White bottom_right size={patch_size}: {dist}")

# Also test checkerboard and random in bottom_right
for patch_type in ['checkerboard', 'random']:
    for patch_size in [3, 4, 5]:
        patched = create_patched_images(patch_type, 'bottom_right', patch_size)
        logits = forward(W, patched)
        preds = logits.argmax(dim=1)
        dist = {}
        for p in preds:
            dist[p.item()] = dist.get(p.item(), 0) + 1
        max_class = max(dist, key=dist.get)
        print(f"{patch_type} bottom_right size={patch_size}: top class {CLASSES[max_class]} ({max_class}) with {dist[max_class]}/50")

print(f"\nPasses left: {passes_left()}")

